<?php
require __DIR__.'/config.php';
header('Access-Control-Allow-Origin: *'); header('Access-Control-Allow-Headers: Content-Type');
$a=$_GET['action']??''; $m=$_SERVER['REQUEST_METHOD'];
try{
 if($a==='health') json_out(['ok'=>true,'app'=>'Loopa']);
 if($a==='register'&&$m==='POST'){ $d=input(); if(empty($d['username'])||empty($d['email'])||empty($d['password'])) json_out(['ok'=>false,'error'=>'Zorunlu alanları doldurun.'],422); $s=db()->prepare('INSERT INTO users(username,email,phone,password_hash,city,district,latitude,longitude,trust_score,status) VALUES(?,?,?,?,?,?,?,?,?,?)'); $s->execute([$d['username'],$d['email'],$d['phone']??'',password_hash($d['password'],PASSWORD_DEFAULT),$d['city']??'İstanbul',$d['district']??'',(float)($d['latitude']??41.0082),(float)($d['longitude']??28.9784),50,'active']); session_start(); $_SESSION['uid']=db()->lastInsertId(); json_out(['ok'=>true]); }
 if($a==='login'&&$m==='POST'){ $d=input(); $s=db()->prepare('SELECT * FROM users WHERE email=? LIMIT 1'); $s->execute([$d['email']??'']); $u=$s->fetch(); if(!$u||!password_verify($d['password']??'',$u['password_hash'])) json_out(['ok'=>false,'error'=>'E-posta veya şifre hatalı.'],401); session_start(); $_SESSION['uid']=$u['id']; json_out(['ok'=>true,'user'=>['id'=>$u['id'],'username'=>$u['username'],'trust_score'=>$u['trust_score']]]); }
 if($a==='logout'){ session_start(); session_destroy(); json_out(['ok'=>true]); }
 if($a==='me'){ $id=user_id(); if(!$id) json_out(['ok'=>true,'user'=>null]); $s=db()->prepare('SELECT id,username,email,phone,city,district,trust_score,status,created_at FROM users WHERE id=?'); $s->execute([$id]); json_out(['ok'=>true,'user'=>$s->fetch()]); }
 if($a==='categories'){ json_out(['ok'=>true,'categories'=>db()->query('SELECT * FROM categories ORDER BY name')->fetchAll()]); }
 if($a==='items'&&$m==='GET'){ $where=['i.status="active"']; $p=[]; if(!empty($_GET['type'])){$where[]='i.sharing_type=?';$p[]=$_GET['type'];} if(!empty($_GET['category'])){$where[]='i.category_id=?';$p[]=$_GET['category'];} if(!empty($_GET['q'])){$where[]='(i.title LIKE ? OR i.description LIKE ?)';$p[]='%'.$_GET['q'].'%';$p[]='%'.$_GET['q'].'%';} $sql='SELECT i.*,u.username,u.trust_score,c.name category_name,(SELECT file_path FROM item_images WHERE item_id=i.id ORDER BY id LIMIT 1) image FROM items i JOIN users u ON u.id=i.owner_id LEFT JOIN categories c ON c.id=i.category_id WHERE '.implode(' AND ',$where).' ORDER BY i.created_at DESC'; $s=db()->prepare($sql);$s->execute($p);json_out(['ok'=>true,'items'=>$s->fetchAll()]); }
 if($a==='item'&&$m==='GET'){ $s=db()->prepare('SELECT i.*,u.username,u.trust_score,c.name category_name FROM items i JOIN users u ON u.id=i.owner_id LEFT JOIN categories c ON c.id=i.category_id WHERE i.id=?');$s->execute([$_GET['id']??0]);$item=$s->fetch(); if(!$item) json_out(['ok'=>false,'error'=>'İlan bulunamadı.'],404); $im=db()->prepare('SELECT * FROM item_images WHERE item_id=?');$im->execute([$item['id']]);$item['images']=$im->fetchAll(); json_out(['ok'=>true,'item'=>$item]); }
 if($a==='items'&&$m==='POST'){ $uid=require_user(); $d=$_POST; $s=db()->prepare('INSERT INTO items(owner_id,category_id,title,description,sharing_type,condition_status,latitude,longitude,approximate_location,delivery_method,max_loan_days,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,"active")'); $s->execute([$uid,$d['category_id']??null,$d['title']??'Adsız eşya',$d['description']??'',$d['sharing_type']??'donation',$d['condition_status']??'used',(float)($d['latitude']??41.0082),(float)($d['longitude']??28.9784),$d['approximate_location']??'Yaklaşık konum',$d['delivery_method']??'Elden teslim',(int)($d['max_loan_days']??0)]); $id=db()->lastInsertId(); if(!empty($_FILES['image']['tmp_name'])){ $ext=strtolower(pathinfo($_FILES['image']['name'],PATHINFO_EXTENSION)); if(!in_array($ext,['jpg','jpeg','png','webp'])) $ext='jpg'; $name='item_'.$id.'_'.time().'.'.$ext; move_uploaded_file($_FILES['image']['tmp_name'],__DIR__.'/../uploads/items/'.$name); db()->prepare('INSERT INTO item_images(item_id,file_path,image_type) VALUES(?,?,"main")')->execute([$id,'../uploads/items/'.$name]); } json_out(['ok'=>true,'id'=>$id]); }
 if($a==='request'&&$m==='POST'){ $uid=require_user();$d=input(); db()->prepare('INSERT INTO item_requests(item_id,requester_id,message,requested_start,requested_end,status) VALUES(?,?,?,?,?,"pending")')->execute([$d['item_id'],$uid,$d['message']??'Bu eşya ile ilgileniyorum.',$d['requested_start']??null,$d['requested_end']??null]); json_out(['ok'=>true]); }
 if($a==='my_requests'){ $uid=require_user(); $s=db()->prepare('SELECT r.*,i.title,i.sharing_type,u.username owner_name FROM item_requests r JOIN items i ON i.id=r.item_id JOIN users u ON u.id=i.owner_id WHERE r.requester_id=? ORDER BY r.created_at DESC');$s->execute([$uid]);json_out(['ok'=>true,'requests'=>$s->fetchAll()]); }
 if($a==='owner_requests'){ $uid=require_user(); $s=db()->prepare('SELECT r.*,i.title,u.username requester_name FROM item_requests r JOIN items i ON i.id=r.item_id JOIN users u ON u.id=r.requester_id WHERE i.owner_id=? ORDER BY r.created_at DESC');$s->execute([$uid]);json_out(['ok'=>true,'requests'=>$s->fetchAll()]); }
 if($a==='request_status'&&$m==='POST'){ $uid=require_user();$d=input(); $s=db()->prepare('UPDATE item_requests r JOIN items i ON i.id=r.item_id SET r.status=? WHERE r.id=? AND i.owner_id=?');$s->execute([$d['status'],$d['id'],$uid]); if($d['status']==='accepted'){ db()->prepare('UPDATE items i JOIN item_requests r ON r.item_id=i.id SET i.status="reserved" WHERE r.id=?')->execute([$d['id']]); } json_out(['ok'=>true]); }
 if($a==='messages'&&$m==='GET'){ $uid=require_user(); $rid=(int)($_GET['request_id']??0); $s=db()->prepare('SELECT m.*,u.username FROM messages m JOIN users u ON u.id=m.sender_id JOIN item_requests r ON r.id=m.request_id JOIN items i ON i.id=r.item_id WHERE m.request_id=? AND (r.requester_id=? OR i.owner_id=?) ORDER BY m.created_at');$s->execute([$rid,$uid,$uid]);json_out(['ok'=>true,'messages'=>$s->fetchAll()]); }
 if($a==='messages'&&$m==='POST'){ $uid=require_user();$d=input(); db()->prepare('INSERT INTO messages(request_id,sender_id,content,moderation_status) VALUES(?,?,?,"ok")')->execute([$d['request_id'],$uid,trim($d['content'])]); json_out(['ok'=>true]); }
 if($a==='stats'){ $out=[]; foreach(['users','items','item_requests','messages'] as $t){$out[$t]=db()->query("SELECT COUNT(*) c FROM $t")->fetch()['c'];} json_out(['ok'=>true,'stats'=>$out]); }
 json_out(['ok'=>false,'error'=>'Geçersiz işlem.'],404);
}catch(Throwable $e){ json_out(['ok'=>false,'error'=>$e->getMessage()],500); }
